// Example service structure per domain
var builder = WebApplication.CreateBuilder(args);

// Services
builder.Services.AddDbContext<AppDbContext>(opt =>
    opt.UseCosmos(
        accountEndpoint: builder.Configuration["Azure:Cosmos:Endpoint"],
        accountKey: builder.Configuration["Azure:Cosmos:Key"],
        databaseName: "SearchAutocompleteDb"
    )
);
builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);
builder.Services.AddMassTransit(opt =>
    opt.UsingRabbitMq((context, cfg) => {
        cfg.Host("rabbitmq", h => {
            h.Username("guest");
            h.Password("guest");
        });
        cfg.ConfigureEndpoints(context);
    })
);

var app = builder.Build();
app.MapGet("/health", () => Results.Ok());
app.MapSearchAutocompleteEndpoints();
app.Run();
